  const top = chart.title === undefined ? MARGIN10 : 80;
  const bottom = top + plotH;
  const right = plotX + plotW;
  const plot = { x: plotX, y: top, w: plotW, h: plotH };
  const items = [];
  let width = Math.max(right + MARGIN10, MARGIN10 + titleW + MARGIN10);
  const height = bottom + (chart.xAxis === undefined ? MARGIN10 : 24 + MARGIN10);
  if (chart.title !== undefined)
    items.push({ kind: "text", x: MARGIN10, y: 56, text: chart.title, anchor: "start", role: ["title"], baseline: "alphabetic" });
