      const padded = { x: r.x - 2, y: r.y - 2, w: r.w + 4, h: r.h + 4 };
      return inside3(r, plot) && !obstacles.some((o) => intersects(padded, o)) && !placed.some((q) => intersects(padded, q.label)) && !dots.some((o) => touchesCircle(padded, o.cx, o.cy, o.r + 1.25));
