var MARGIN11 = 24;
var TITLE_LINE2 = 18;
var TITLE_GAP = 24;
var TOKEN_H = 32;
var TOKEN_MIN_W = 48;
var TOKEN_PAD = 32;
var TOKEN_ADVANCE = 8;
var SEQ_GAP = 24;
var CHOICE_GAP = 8;
var RULE_GAP = 40;
var RAIL_CLEAR = 24;
var FORK_X = 16;
var BLOCK_PAD = 48;
var LOOP_INSET = 32;
var ORDER_ROOM = 16;
var ORDER_DX = 12;
var ORDER_DY = 10;
var NAME_GAP3 = 24;
var END_STUB = 24;
var CHIP_H3 = 24;
var CHIP_GAP = 8;
var PORT_R5 = 4;
