  labels.forEach((l, i) => {
    lines.push(spansOf([padEnd(cut2(l, labelW), labelW), "dim"], cols.map((c, j) => `  ${padStart(c.cells[i] ?? "", colW[j] ?? 0)}`).join("")));
  });
