      const group = which === "from" ? e.fromGroup : e.toGroup;
      const side = which === "from" ? e.fromSide : e.toSide;
      return which === "from" ? `${nameOf(id)}${group ? "{group}" : ""}:${side}` : `${side}:${nameOf(id)}${group ? "{group}" : ""}`;
