    const cx = (box.x0 + box.x1) / 2;
    lines.forEach((l, i) => noteItems.push({ kind: "text", x: cx, y: box.y0 + LINE_H3 + i * LINE_H3, text: l, anchor: "middle", role: ["sub"] }));
