    items.push({ kind: "text", x: MARGIN20, y: 56, text: map.title, anchor: "start", role: ["title"] });
  for (const bx of boundaries)
    items.push({ kind: "line", points: [{ x: bx, y: top }, { x: bx, y: bottom }], role: ["grid"] });
